def gen(rng):
    def fmt(cs):
        return str(len(cs)) + '\n' + '\n'.join(f'{x} {y} {r}' for x, y, r in cs)
    tests = [
        fmt([(2, 2, 1)]), fmt([(2, 2, 2), (3, 4, 1)]), fmt([(0, 0, 1)]), fmt([(100000, 100000, 100)]),
        fmt([(5, 5, 3), (5, 5, 3)]), fmt([(5, 5, 3), (5, 5, 1)]), fmt([(0, 0, 1), (2, 0, 1)]),
        fmt([(0, 0, 100), (100, 0, 100), (200, 0, 100)]), fmt([(10, 10, 1), (10, 12, 1), (10, 11, 1)]),
    ]
    for n in (2, 3, 4, 6, 8):
        for _ in range(4):
            cs = [(rng.randint(0, 12), rng.randint(0, 12), rng.randint(1, 4)) for _ in range(n)]
            tests.append(fmt(cs))
    for _ in range(4):
        cs = [(rng.randint(0, 150), rng.randint(0, 150), rng.randint(1, 100)) for _ in range(rng.randint(1, 3))]
        tests.append(fmt(cs))
    n = 1000
    tests.append(fmt([(rng.randint(0, 10**5), rng.randint(0, 10**5), rng.randint(1, 100)) for _ in range(n)]))
    tests.append(fmt([(rng.randint(10**5 - 300, 10**5), rng.randint(10**5 - 300, 10**5), 100) for _ in range(n)]))
    tests.append(fmt([(rng.randint(0, 10**5), rng.randint(0, 10**5), 100) for _ in range(n)]))
    tests.append(fmt([(50000 + 10 * (i % 40), 50000 + 10 * (i // 40), 100) for i in range(n)]))
    tests.append(fmt([(100000, 100000, 100)] * n))
    return tests
